-- Source: sql/analysis/10_analytical_views.sql
{{ config(materialized='view') }}

SELECT
  w.retail_week_key,
  w.retail_year,
  w.retail_week,
  w.retail_week_label,
  w.retail_half,
  w.is_comparable_week,
  c.category,
  COALESCE(s.sales_lines, 0) AS sales_lines,
  COALESCE(s.units_sold, 0) AS units_sold,
  COALESCE(s.transactions_with_category, 0) AS transactions_with_category,
  COALESCE(s.gross_sales, 0) AS gross_sales,
  COALESCE(s.discount_value, 0) AS discount_value,
  COALESCE(s.sales_revenue, 0) AS sales_revenue,
  COALESCE(r.returns_value, 0) AS returns_value,
  COALESCE(s.sales_revenue, 0) - COALESCE(r.returns_value, 0) AS net_revenue,
  COALESCE(s.cost_of_sales, 0) - COALESCE(r.restock_cost_credit, 0) AS cogs,
  (
    COALESCE(s.sales_revenue, 0) - COALESCE(r.returns_value, 0)
  ) - (
    COALESCE(s.cost_of_sales, 0) - COALESCE(r.restock_cost_credit, 0)
  ) AS gross_margin,
  COALESCE(s.promo_sales_revenue, 0) AS promo_sales_revenue,
  COALESCE(r.returned_units, 0) AS returned_units,
  CAST(COALESCE(s.sales_revenue, 0) AS DOUBLE) / NULLIF(CAST(s.units_sold AS DOUBLE), 0) AS asp,
  CAST(COALESCE(s.promo_sales_revenue, 0) AS DOUBLE) / NULLIF(CAST(s.sales_revenue AS DOUBLE), 0) AS promo_revenue_share,
  CAST(COALESCE(r.returns_value, 0) AS DOUBLE) / NULLIF(CAST(s.sales_revenue AS DOUBLE), 0) AS return_rate_value
FROM (
  SELECT DISTINCT
    d.retail_week_key,
    p.category
  FROM {{ ref('dim_date') }} AS d
  CROSS JOIN {{ ref('dim_product') }} AS p
  WHERE
    d.date_key <> -1
) AS c
JOIN {{ ref('dim_retail_week') }} AS w
  ON w.retail_week_key = c.retail_week_key
LEFT JOIN (
  SELECT
    d.retail_week_key,
    p.category,
    COUNT(*) AS sales_lines,
    SUM(CAST(f.quantity AS INT)) AS units_sold,
    COUNT(DISTINCT f.transaction_id) AS transactions_with_category,
    CAST(SUM(f.gross_amount) AS DECIMAL(19, 2)) AS gross_sales,
    CAST(SUM(f.discount_amount) AS DECIMAL(19, 2)) AS discount_value,
    CAST(SUM(f.sales_revenue) AS DECIMAL(19, 2)) AS sales_revenue,
    CAST(SUM(f.cost_amount) AS DECIMAL(19, 2)) AS cost_of_sales,
    CAST(SUM(CASE WHEN f.is_promoted = 1 THEN f.sales_revenue ELSE 0 END) AS DECIMAL(19, 2)) AS promo_sales_revenue
  FROM {{ ref('fact_sales') }} AS f
  JOIN {{ ref('dim_date') }} AS d
    ON d.date_key = f.date_key
  JOIN {{ ref('dim_product') }} AS p
    ON p.product_key = f.product_key
  GROUP BY
    d.retail_week_key,
    p.category
) AS s
  ON s.retail_week_key = c.retail_week_key AND s.category = c.category
LEFT JOIN (
  SELECT
    d.retail_week_key,
    p.category,
    CAST(SUM(r.refund_value) AS DECIMAL(19, 2)) AS returns_value,
    CAST(SUM(r.restock_cost_credit) AS DECIMAL(19, 4)) AS restock_cost_credit,
    SUM(CAST(r.return_quantity AS INT)) AS returned_units
  FROM {{ ref('fact_returns') }} AS r
  JOIN {{ ref('dim_date') }} AS d
    ON d.date_key = r.return_date_key
  JOIN {{ ref('dim_product') }} AS p
    ON p.product_key = r.product_key
  GROUP BY
    d.retail_week_key,
    p.category
) AS r
  ON r.retail_week_key = c.retail_week_key AND r.category = c.category
WHERE
  NOT s.sales_lines IS NULL OR NOT r.returns_value IS NULL
